package io.knowledgebrain.collaboration;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController
@ConditionalOnProperty(name="brain.collaboration.api.enabled",havingValue="true")
@RequestMapping("/api/groups/{groupId}/courses/{courseId}")
final class CourseEnrollmentController {
 private final CourseEnrollmentStore store;private final StudyController gate;private final MeterRegistry metrics;
 CourseEnrollmentController(CourseEnrollmentStore store,StudyController gate,MeterRegistry metrics){this.store=store;this.gate=gate;this.metrics=metrics;}
 static String tag(long version){return "\"ce"+version+"\"";}
 static long expected(HttpServletRequest r){var values=Collections.list(r.getHeaders("If-Match"));if(values.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(values.size()!=1||!values.getFirst().matches("\"ce(0|[1-9][0-9]{0,18})\""))throw GroupInput.bad();try{return Long.parseLong(values.getFirst().substring(3,values.getFirst().length()-1));}catch(NumberFormatException e){throw GroupInput.bad();}}
 private boolean writer(StudyController.Access a){return Set.of("OWNER","MEMBER").contains(a.role());}
 private StudyController.Access owner(UUID group,HttpServletRequest r){var a=gate.participant(group,r,false,gate.trace(r));if(!a.role().equals("OWNER"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Group owner required");return a;}
 private ResponseEntity<?> value(CourseEnrollmentStore.Enrollment v){return ResponseEntity.ok().eTag(tag(v.version())).cacheControl(CacheControl.noStore()).body(v);}
 private void read(String kind){metrics.counter("brain.collaboration.course.enrollment.reads","type",kind).increment();}
 @GetMapping("/enrollment") ResponseEntity<?> mine(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());gate.empty(r);UUID group=GroupInput.id(groupId),course=GroupInput.id(courseId);var a=gate.participant(group,r,false,gate.trace(r));var v=store.mine(group,a.space(),course,a.actor(),writer(a));read("mine");return ResponseEntity.ok().eTag(tag(v.enrollment().version())).cacheControl(CacheControl.noStore()).body(v);}
 @PutMapping("/enrollment") ResponseEntity<?> change(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());UUID group=GroupInput.id(groupId),course=GroupInput.id(courseId);String trace=gate.trace(r);var a=gate.participant(group,r,true,trace);long expected=expected(r);String state=CourseEnrollmentStore.input(gate.jsonBody(r));if(state.equals("ENROLLED")&&!writer(a))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Course enrollment requires OWNER or MEMBER");var v=store.change(group,a.space(),course,a.actor(),expected,state,trace.substring(3,35));metrics.counter("brain.collaboration.course.enrollment.changes","type",state.equals("ENROLLED")?"enroll":"withdraw").increment();org.slf4j.LoggerFactory.getLogger(getClass()).info("course_enrollment type={} enrollment_id={} trace_id={}",state,v.enrollmentId(),trace.substring(3,35));return value(v);}
 @GetMapping("/enrollment/revisions") ResponseEntity<?> mineHistory(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r)throws IOException{gate.query(r,Set.of("before","limit"));gate.empty(r);UUID group=GroupInput.id(groupId),course=GroupInput.id(courseId);long before=gate.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)gate.number(r.getParameter("limit"),5,10);var a=gate.participant(group,r,false,gate.trace(r));read("mine_history");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.mineHistory(group,a.space(),course,a.actor(),before,limit));}
 @GetMapping("/enrollments") ResponseEntity<?> list(@PathVariable String groupId,@PathVariable String courseId,HttpServletRequest r)throws IOException{gate.query(r,Set.of("after","limit"));gate.empty(r);UUID group=GroupInput.id(groupId),course=GroupInput.id(courseId),after=r.getParameter("after")==null?null:GroupInput.id(r.getParameter("after"));int limit=(int)gate.number(r.getParameter("limit"),20,100);var a=owner(group,r);read("catalog");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.list(group,a.space(),course,after,limit));}
 @GetMapping("/enrollments/{enrollmentId}") ResponseEntity<?> get(@PathVariable String groupId,@PathVariable String courseId,@PathVariable String enrollmentId,HttpServletRequest r)throws IOException{gate.query(r,Set.of());gate.empty(r);UUID group=GroupInput.id(groupId),course=GroupInput.id(courseId),id=GroupInput.id(enrollmentId);var a=gate.participant(group,r,false,gate.trace(r));read("current");return value(store.get(group,a.space(),course,id,a.actor(),a.role().equals("OWNER")));}
 @GetMapping("/enrollments/{enrollmentId}/revisions") ResponseEntity<?> history(@PathVariable String groupId,@PathVariable String courseId,@PathVariable String enrollmentId,HttpServletRequest r)throws IOException{gate.query(r,Set.of("before","limit"));gate.empty(r);UUID group=GroupInput.id(groupId),course=GroupInput.id(courseId),id=GroupInput.id(enrollmentId);long before=gate.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)gate.number(r.getParameter("limit"),5,10);var a=gate.participant(group,r,false,gate.trace(r));read("history");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(group,a.space(),course,id,a.actor(),a.role().equals("OWNER"),before,limit));}
}
